describe('Async Form Submission - Submit Button Disabled Until Resolved', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/async-form');
    cy.intercept('POST', '/api/submit-form', {
      delay: 2000,
      statusCode: 200,
      body: { success: true, message: 'Form submitted successfully' }
    }).as('formSubmission');
  });

  it('should disable submit button during async form submission and re-enable after resolution', () => {
    // Fill form fields
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="name"]').type('John Doe');
    cy.get('textarea[name="message"]').type('Test message');

    // Get submit button and verify it's enabled initially
    cy.get('button[type="submit"]').should('not.be.disabled');

    // Click submit button
    cy.get('button[type="submit"]').click();

    // Verify button is disabled during submission
    cy.get('button[type="submit"]').should('be.disabled');
    cy.get('button[type="submit"]').should('have.text', 'Submitting...');

    // Wait for the async request to complete
    cy.wait('@formSubmission');

    // Verify button is re-enabled after submission completes
    cy.get('button[type="submit"]').should('not.be.disabled');
    cy.get('button[type="submit"]').should('have.text', 'Submit');

    // Verify success message is displayed
    cy.get('.success-message').should('be.visible');
    cy.get('.success-message').should('contain', 'Form submitted successfully');
  });

  it('should handle form submission failure and re-enable button with error message', () => {
    // Override intercept to simulate failure
    cy.intercept('POST', '/api/submit-form', {
      delay: 1500,
      statusCode: 400,
      body: { success: false, message: 'Email already exists' }
    }).as('formSubmissionFailure');

    // Fill form fields
    cy.get('input[name="email"]').type('existing@example.com');
    cy.get('input[name="name"]').type('Jane Doe');
    cy.get('textarea[name="message"]').type('Another test message');

    // Click submit button
    cy.get('button[type="submit"]').click();

    // Verify button is disabled during submission
    cy.get('button[type="submit"]').should('be.disabled');

    // Wait for the failed request
    cy.wait('@formSubmissionFailure');

    // Verify button is re-enabled after failure
    cy.get('button[type="submit"]').should('not.be.disabled');

    // Verify error message is displayed
    cy.get('.error-message').should('be.visible');
    cy.get('.error-message').should('contain', 'Email already exists');
  });

  it('should prevent multiple concurrent submissions when button is clicked multiple times', () => {
    cy.intercept('POST', '/api/submit-form', {
      delay: 3000,
      statusCode: 200,
      body: { success: true, message: 'Form submitted successfully' }
    }).as('formSubmission');

    // Fill form fields
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="name"]').type('John Doe');
    cy.get('textarea[name="message"]').type('Test message');

    // Click submit button
    cy.get('button[type="submit"]').click();

    // Verify button is disabled
    cy.get('button[type="submit"]').should('be.disabled');

    // Attempt to click disabled button multiple times
    cy.get('button[type="submit"]').click({ force: true });
    cy.get('button[type="submit"]').click({ force: true });

    // Verify only one request was made
    cy.get('@formSubmission.all').should('have.length', 1);

    // Wait for submission to complete
    cy.wait('@formSubmission');

    // Verify button is re-enabled
    cy.get('button[type="submit"]').should('not.be.disabled');
  });

  it('should maintain form data and button state during async submission', () => {
    const testEmail = 'persist@example.com';
    const testName = 'Persistent User';
    const testMessage = 'Data should persist';

    // Fill form fields
    cy.get('input[name="email"]').type(testEmail);
    cy.get('input[name="name"]').type(testName);
    cy.get('textarea[name="message"]').type(testMessage);

    // Click submit button
    cy.get('button[type="submit"]').click();

    // Verify button is disabled
    cy.get('button[type="submit"]').should('be.disabled');

    // Verify form data is still present during submission
    cy.get('input[name="email"]').should('have.value', testEmail);
    cy.get('input[name="name"]').should('have.value', testName);
    cy.get('textarea[name="message"]').should('have.value', testMessage);

    // Wait for submission
    cy.wait('@formSubmission');

    // Verify form is cleared after successful submission
    cy.get('input[name="email"]').should('have.value', '');
    cy.get('input[name="name"]').should('have.value', '');
    cy.get('textarea[name="message"]').should('have.value', '');

    // Verify button is re-enabled and ready for new submission
    cy.get('button[type="submit"]').should('not.be.disabled');
  });
});
